from generate import *

def anim(actor,name,action,estimate=.03):
 base=json.loads((R/(actor+'.json')).read_text())['image']
 return request(actor+'_'+name,'animate-with-text',{'reference_image':base,'description':('Lean green-skinned youth, black ponytail, dark green tunic, ochre sash, brown leather boots and bracers.' if actor=='kael' else 'Spectral dark violet Tenebri shade humanoid guard, pale glowing eyes, purple tunic, curved silver blade. Preserve reference character precisely.'),'action':action+' Side profile facing RIGHT throughout, fixed camera and scale.','image_size':{'width':64,'height':64},'n_frames':4,'view':'side','direction':'east'},estimate)
if __name__=='__main__':
 actions={'idle':'Subtle breathing idle loop standing in place, empty hands.','jump':'Jump takeoff then tucked knees ascending, arms raised, empty hands.','fall':'Falling downward feet below hips and arms reaching forward, empty hands.','hang':'Hanging from a ledge above with both hands extended overhead, legs dangling below.','climb':'Pulling up onto a ledge with arms overhead, lift one knee onto the ledge then stand.','attack':'Draw a curved short sword and slash forward to the right, clear anticipation strike recovery.','block':'Raise curved short sword in front to parry an incoming attack from the right.','hurt':'Recoil from a blow, stagger backward, recover footing.','death':'Collapse to the ground and lie motionless, body extends horizontally.'}
 for name,action in actions.items():
  if not (R/('kael_'+name+'.json')).exists():anim('kael',name,action)
 request('shade','create-image-pixflux',{'description':'Full body spectral Tenebri shade guard, dark violet humanoid with wispy edges and pale glowing eyes, narrow hooded head, dark purple layered leather tunic, curved silver blade in right hand, tall lean realistic proportions. Side profile facing RIGHT, cinematic Prince of Persia pixel art, 48 pixel tall body centered in 64 pixel canvas. Transparent background, no ground shadow.','image_size':{'width':64,'height':64},'view':'side','direction':'east','no_background':True},.015)
 for name,action in {'idle':'Subtle breathing guard stance idle loop holding curved blade.','walk':'Walk in place to the right, steady full stride, curved blade held.','attack':'Slash curved blade toward the right with anticipation strike recovery.','block':'Raise curved sword to block and parry from the right.','hurt':'Stagger backwards from being struck then recover.','death':'Collapse to the floor and dissolve, final pose lying horizontally.'}.items():anim('shade',name,action)
 print('Character batch done',spent(),flush=True)
